async (page) => {
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.locator('.capsule-link').click();
  const open = await page.locator('#gachaModal').evaluate(el => getComputedStyle(el).display);
  await page.locator('[data-gacha="single"]').click();
  const single = await page.evaluate(() => ({coins: document.querySelector('#coinCount').textContent, pieces: document.querySelector('#wardrobeCount').textContent, result: document.querySelector('#resultCopy').textContent}));
  await page.locator('#continueBtn').click();
  await page.evaluate(() => { const s = JSON.parse(localStorage.getItem('starlet-atelier-save')); s.coins = 0; localStorage.setItem('starlet-atelier-save', JSON.stringify(s)); });
  await page.reload();
  await page.locator('.capsule-link').click();
  await page.locator('[data-gacha="rare"]').click();
  const insufficient = await page.evaluate(() => ({coins: document.querySelector('#coinCount').textContent, toast: document.querySelector('#toast').textContent}));
  await page.evaluate(() => {
    const s = JSON.parse(localStorage.getItem('starlet-atelier-save'));
    s.coins = 100;
    s.owned = ['rose-dress','moon-gown','sunset-dress','garden-dress','starlet-dress','soft-waves','golden-bun','midnight-bob','rose-braid','pink-heels','moon-heels','gold-shoes','garden-shoes','star-earrings','pearl-necklace','moon-crown','flower-bag','sun-charm'];
    localStorage.setItem('starlet-atelier-save', JSON.stringify(s));
    Math.random = () => 0;
  });
  await page.reload();
  await page.locator('.capsule-link').click();
  await page.locator('[data-gacha="single"]').click();
  const duplicate = await page.evaluate(() => ({coins: document.querySelector('#coinCount').textContent, copy: document.querySelector('#resultCopy').textContent, pieces: document.querySelector('#wardrobeCount').textContent}));
  await page.reload();
  const persisted = await page.evaluate(() => ({coins: document.querySelector('#coinCount').textContent, pieces: document.querySelector('#wardrobeCount').textContent}));
  return {open, single, insufficient, duplicate, persisted};
}

